CSS_IMPORT = 'import "./styles/cut-approved-stripes-v3.css";'

def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def atomic_write(path: Path, content: bytes) -> None:
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,temp=tempfile.mkstemp(prefix='.cut-design-v3-',suffix='.tmp',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp,path)
    finally:
        if os.path.exists(temp): os.unlink(temp)

def main() -> int:
    print('=== CUT Improvement Auto / Approved stripes + Toyota Supra v3 ===')
    script = Path(__file__).resolve()
    project = script.parent.parent
    if script.parent.name.lower() != 'scripts' or not (project/'backend/app/main.py').is_file():
        raise RuntimeError('Put this file in the existing PROJECT/scripts directory.')
    app = project/'frontend/src/App.tsx'
    layout = project/'frontend/src/styles/cut-dashboard-layout.css'
    if not app.is_file() or not layout.is_file():
        raise RuntimeError('Approved React layout is missing; no changes made.')
    original_app = app.read_bytes()
    try:
        app_text=original_app.decode('utf-8-sig')
    except UnicodeDecodeError:
        raise RuntimeError('Cannot decode App.tsx; no changes made.')
    required=('.cut-modern-app', 'cut-welcome-banner', 'cut-masthead', 'cut-dashboard-layout.css')
    combined=app_text + layout.read_text(encoding='utf-8-sig')
    if not all(marker in combined for marker in required):
        raise RuntimeError('App does not match installed approved dashboard; no changes made.')
    # No custom code replacement: add ONLY the final CSS import at the end of the style imports.
    if CSS_IMPORT in app_text:
        updated_app=original_app
    else:
        style_imports=list(re.finditer(r'^import "\./styles/[a-zA-Z0-9_-]+\.css";[ \t]*$',app_text,re.MULTILINE))
        if not style_imports:
            raise RuntimeError('No known stylesheet imports in App.tsx; no changes made.')
        pos=style_imports[-1].end()
        new_app_text=app_text[:pos]+'\n'+CSS_IMPORT+app_text[pos:]
        updated_app=new_app_text.encode('utf-8')
    expected={}
    for rel,record in FILES.items():
        blob=zlib.decompress(base64.b64decode(record['data']))
        if digest(blob)!=record['sha256']:
            raise RuntimeError('Embedded resource failed SHA-256 validation: '+rel)
        target=project/rel
        if target.exists() and target.is_symlink():
            raise RuntimeError('Refusing to overwrite a symlink: '+rel)
        if target.is_file() and digest(target.read_bytes()) != record['sha256']:
            raise RuntimeError('Existing design resource differs; refusing: '+rel)
        expected[target]=blob
    if app.is_symlink():
        raise RuntimeError('App.tsx is a symlink; refusing update.')
    change={}
    for target,blob in expected.items():
        if not target.is_file(): change[target]=blob
    if updated_app != original_app: change[app]=updated_app
    if not change:
        print('OK: approved design v3 already installed; nothing to do.')
        return 0
    stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    archive=project.parent/'CUT_Improvement_Auto_DevArchive'/'approved_stripes_v3_backups'/stamp
    archive.mkdir(parents=True,exist_ok=False)
    prior={}
    for target in change:
        existing=target.read_bytes() if target.is_file() else None
        prior[target]=existing
        if existing is not None:
            backup=archive/target.relative_to(project)
            backup.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(target,backup)
            if digest(backup.read_bytes()) != digest(existing):
                raise RuntimeError('Backup verification failed; no project files modified.')
    changed=[]
    try:
        # Write resources first, import last so Vite never sees a missing stylesheet.
        for target in sorted(change,key=lambda p: p==app):
            atomic_write(target,change[target])
            if digest(target.read_bytes())!=digest(change[target]):
                raise RuntimeError('Write verification failed: '+str(target))
            changed.append(target)
    except BaseException:
        for target in reversed(changed):
            old=prior[target]
            if old is None:target.unlink(missing_ok=True)
            else: atomic_write(target,old)
        raise
    print('OK: identical geometry for Light and Dark: masthead, banner, metrics, sections.')
    print('OK: gold racing stripes in sidebar and dark section headers (both themes).')
    print('OK: Toyota Supra artwork installed in Light and Dark welcome banners.')
    print('OK: repeated sidebar branding is hidden (header branding retained).')
    print('OK: theme selector, real dashboard data, navigation and API untouched.')
    print('BACKUP:',archive)
    print('CHANGED:',', '.join(str(p.relative_to(project)) for p in changed))
    print('UNCHANGED: active frontend release, frontend/dist, backend, DB, MAX, .env, photos, backups, Git.')
    print('NEXT: preview at http://127.0.0.1:5173/ in Vite, no build/commit yet.')
    return 0

if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as exc:
        print('INSTALL FAILED:',exc,file=sys.stderr)
        raise SystemExit(1)
